template <bool B>
inline bool VerifyPayload(::flatbuffers::VerifierTemplate<B> &verifier, const void *obj, Payload type) {
  switch (type) {
    case Payload::NONE: {
      return true;
    }
    case Payload::LoginRequest: {
      auto ptr = reinterpret_cast<const HeavenLogin::LoginRequest *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Payload::LoginResponse: {
      auto ptr = reinterpret_cast<const HeavenLogin::LoginResponse *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Payload::RegisterRequest: {
      auto ptr = reinterpret_cast<const HeavenLogin::RegisterRequest *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Payload::RegisterResponse: {
      auto ptr = reinterpret_cast<const HeavenLogin::RegisterResponse *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Payload::CreateCharacterRequest: {
      auto ptr = reinterpret_cast<const HeavenLogin::CreateCharacterRequest *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Payload::CharacterListResponse: {
      auto ptr = reinterpret_cast<const HeavenLogin::CharacterListResponse *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Payload::SelectCharacterRequest: {
      auto ptr = reinterpret_cast<const HeavenLogin::SelectCharacterRequest *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Payload::SelectCharacterResponse: {
      auto ptr = reinterpret_cast<const HeavenLogin::SelectCharacterResponse *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Payload::DeleteCharacterRequest: {
      auto ptr = reinterpret_cast<const HeavenLogin::DeleteCharacterRequest *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Payload::ReleasePartnerRequest: {
      auto ptr = reinterpret_cast<const HeavenLogin::ReleasePartnerRequest *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Payload::SetPartyRequest: {
      auto ptr = reinterpret_cast<const HeavenLogin::SetPartyRequest *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

template <bool B>
inline bool VerifyPayloadVector(::flatbuffers::VerifierTemplate<B> &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<Payload> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyPayload(
        verifier,  values->Get(i), types->GetEnum<Payload>(i))) {
      return false;
    }
  }
  return true;
}

